 import { MeshBasicNodeMaterial, Mesh, PlaneGeometry } from 'three/webgpu';
import { uv, vec3, uniform, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function hexToVec3(hex) {
  const n = parseInt(hex.replace('#', ''), 16);
  return vec3(
    ((n >> 16) & 255) / 255,
    ((n >> 8) & 255) / 255,
    (n & 255) / 255
  );
}

export default function createNode(config, ctx) {
  const { Group, Color } = ctx.THREE;
  const colors = config.intent?.visualSpec?.colors || config.colors || {};
  const ink = colors.ink || '#16161d';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  const root = new Group();

  const rowWidth = 4.2;
  const rowHeight = 0.72;

  const backdropGeo = new PlaneGeometry(rowWidth, rowHeight);
  const inkNode = uniform(hexToVec3(ink));
  const surfaceNode = uniform(hexToVec3(surface));
  const gradientNode = mix(inkNode, surfaceNode, smoothstep(uv().y, 0, 1));
  const backdropMat = new MeshBasicNodeMaterial({ colorNode: gradientNode });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.06;
  root.add(backdrop);

  const glowMat = new MeshBasicNodeMaterial({
    color: new Color(accent),
    transparent: true,
    opacity: 0,
    side: 2,
  });
  const glow = new Mesh(new PlaneGeometry(rowWidth + 0.12, rowHeight + 0.12), glowMat);
  glow.position.z = -0.07;
  root.add(glow);

  const mainMat = new MeshBasicNodeMaterial({
    color: new Color(paper).multiplyScalar(0.22),
    transparent: true,
    opacity: 0.95,
    side: 2,
  });
  const main = new Mesh(new PlaneGeometry(rowWidth - 0.08, rowHeight - 0.08), mainMat);
  main.position.z = -0.02;
  root.add(main);

  const dividerMat = new MeshBasicNodeMaterial({
    color: new Color(accent),
    transparent: true,
    opacity: 0.5,
  });
  const divider = new Mesh(new PlaneGeometry(rowWidth - 0.6, 0.012), dividerMat);
  divider.position.set(0, -rowHeight * 0.25, 0.005);
  root.add(divider);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = ctx.THREE.RepeatWrapping;
      tex.wrapT = ctx.THREE.RepeatWrapping;
      tex.repeat.set(2, 0.35);
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      mainMat.map = tex;
      mainMat.needsUpdate = true;
    });
  }

  const timelines = [];

  const baseZ = root.position.z;

  const showGlow = () => {
    const t = gsap.timeline();
    timelines.push(t);
    t.to(glowMat, { opacity: 0.7, duration: 0.25, ease: 'power2.out' });
    t.to(
      root.position,
      { z: baseZ + 0.15, duration: 0.35, ease: 'power3.out' },
      0
    );
    t.to(main.scale, { x: 1.01, y: 1.01, duration: 0.35, ease: 'power2.out' }, 0);
  };

  const hideGlow = () => {
    const t = gsap.timeline();
    timelines.push(t);
    t.to(glowMat, { opacity: 0, duration: 0.25, ease: 'power2.out' });
    t.to(
      root.position,
      { z: baseZ, duration: 0.35, ease: 'power3.out' },
      0
    );
    t.to(main.scale, { x: 1, y: 1, duration: 0.35, ease: 'power2.out' }, 0);
  };

  root.userData.handlers = {
    hover: showGlow,
    pointerenter: showGlow,
    pointerleave: hideGlow,
    click: () => {
      const t = gsap.timeline({
        onComplete: () => {
          ctx.emit('hub-collection.select', { id: config.id });
        },
      });
      timelines.push(t);
      t.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
      t.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });
    },
  };

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    timelines.length = 0;
    backdropGeo.dispose();
    backdropMat.dispose();
    main.geometry.dispose();
    mainMat.dispose();
    glow.geometry.dispose();
    glowMat.dispose();
    divider.geometry.dispose();
    dividerMat.dispose();
  };

  return root;
}
